-- Dominio: Contenido y preguntas
-- Banco de preguntas de selección múltiple para Lengua y Literatura,
-- Currículum Regular, 8° Básico (D.S. 614/2013), 4 ejes: Lectura, Escritura,
-- Comunicación Oral, Investigación. 4 preguntas por cada uno de los 17
-- objetivos de aprendizaje ya cargados en
-- supabase/seed/0015_curriculum_lenguaje_regular_7basico_2medio.sql
-- (unit_id + level_id + short_name, NUNCA ids hardcodeados).
--
-- Mismo criterio editorial, de validación, de formato y de idempotencia
-- documentado en supabase/seed/0064_question_bank_lenguaje_regular_
-- 7basico.sql -- no se repite aquí el detalle completo. Resumen:
--   - `review_status = 'borrador'`, `validation_status =
--     'ai_generated_review_required'`, `is_active = true`,
--     `source_type = 'validapp_original'`, `framework_id` NULL.
--   - NINGUNA pregunta de este archivo se muestra a estudiantes hasta
--     revisión y aprobación humana individual (ver 0023, 0064 y
--     `lib/data/essays.ts`).
--   - Fragmentos citados dentro de los enunciados son creaciones originales
--     de ValidApp con fines pedagógicos, no citas de obras reales.
--   - `content_hash` queda NULL (se calcula en TypeScript, no en SQL); este
--     archivo se validó localmente con el mismo script Node ad-hoc que
--     replica `validateQuestion`/`computeContentHash`/`textSimilarity`.
--   - Idempotencia con `where not exists (...)` sobre
--     `learning_objective_id` + `prompt`. Seed SOLO local.

-- ============================================================================
-- EJE: LECTURA — 8° BÁSICO (5 objetivos x 4 preguntas = 20)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Comparación de obras de distintas épocas y culturas', 'Al comparar una obra literaria medieval con una obra contemporánea, ¿qué aspecto resulta más relevante analizar?', '["El número de páginas de cada obra","Las diferencias y semejanzas en los valores y visión de mundo que reflejan","El precio de venta de cada libro","El tamaño de la portada de cada edición"]', 1, 'Comparar obras de distintas épocas implica analizar cómo cambian los valores y la visión de mundo representados, más allá de aspectos materiales del libro.', 'inicial', 60),
  ('Comparación de obras de distintas épocas y culturas', 'Una novela del siglo XIX retrata el honor como valor central, mientras una novela actual explora la identidad personal. ¿Qué permite explicar esta diferencia?', '["Que una de las dos obras está mal escrita","Que los valores y preocupaciones de una época influyen en los temas literarios","Que la literatura antigua no trata sobre personas reales","Que ambas obras tratan exactamente el mismo tema"]', 1, 'Los temas que aborda una obra literaria suelen reflejar los valores y preocupaciones propios del contexto en que fue escrita.', 'intermedia', 90),
  ('Comparación de obras de distintas épocas y culturas', '¿Cuál de las siguientes NO es una razón válida para comparar obras de distintas épocas o culturas?', '["Identificar cómo cambian los valores sociales representados","Reconocer similitudes y diferencias en la forma de narrar","Determinar cuál obra es superior según el gusto personal del lector","Comprender el contexto histórico que influye en cada obra"]', 2, 'Comparar obras busca comprender diferencias culturales e históricas, no establecer cuál obra es "mejor" según una preferencia personal.', 'intermedia', 90),
  ('Comparación de obras de distintas épocas y culturas', 'Un estudiante compara un mito griego con una leyenda mapuche y observa que ambos explican fenómenos naturales mediante seres sobrenaturales. ¿Qué conclusión sobre literatura de distintas culturas permite esta comparación?', '["Ambas culturas copiaron sus historias entre sí","Culturas distintas pueden compartir funciones narrativas similares, aunque con elementos propios","Solo una de las dos culturas tiene una tradición oral válida","Las leyendas no tienen relación alguna con los mitos"]', 1, 'Distintas culturas pueden desarrollar de forma independiente narrativas con funciones similares (explicar el mundo), conservando a la vez elementos propios de su cosmovisión.', 'avanzada', 120),

  ('Comprensión crítica de textos de los medios', '¿Qué caracteriza a una columna de opinión publicada en un medio de comunicación?', '["Presenta exclusivamente hechos, sin ninguna valoración","Expresa el punto de vista argumentado de su autor sobre un tema","Es siempre un texto oficial del medio, no de un autor particular","No puede incluir ningún dato o cifra"]', 1, 'Una columna de opinión se caracteriza por presentar el punto de vista argumentado de un autor sobre un tema, a diferencia de una noticia informativa.', 'inicial', 60),
  ('Comprensión crítica de textos de los medios', 'Una noticia sobre un mismo hecho es reportada de forma distinta por dos medios de comunicación. ¿Qué estrategia de comprensión crítica es más adecuada?', '["Creer solo en el medio que se conoce hace más tiempo","Comparar ambas versiones y evaluar qué datos o énfasis usa cada una","Ignorar ambas noticias por tratarse de un mismo hecho","Elegir la versión más breve porque es más fácil de leer"]', 1, 'Comparar críticamente ambas versiones permite identificar qué datos y énfasis usa cada medio, en vez de aceptar una sin cuestionarla.', 'intermedia', 90),
  ('Comprensión crítica de textos de los medios', '¿Cuál de las siguientes estrategias NO corresponde a una comprensión crítica de textos de los medios?', '["Identificar el punto de vista del medio o autor","Verificar si los datos entregados pueden contrastarse con otras fuentes","Aceptar la información solo porque el titular es llamativo","Reconocer la intención comunicativa del texto (informar, opinar, persuadir)"]', 2, 'Aceptar información solo por un titular llamativo es contrario a la comprensión crítica, que exige verificar datos e identificar intenciones comunicativas.', 'intermedia', 90),
  ('Comprensión crítica de textos de los medios', 'Un reportaje usa un titular alarmante, pero el cuerpo del texto matiza la información con datos más moderados. ¿Qué debería hacer un lector crítico?', '["Basar su opinión únicamente en el titular","Leer el texto completo y contrastar el titular con el contenido real","Compartir el titular sin leer el resto del texto","Ignorar completamente el reportaje por tener un titular llamativo"]', 1, 'Un lector crítico contrasta el titular con el desarrollo completo del texto antes de formarse una opinión sobre el contenido.', 'avanzada', 120),

  ('Lenguaje figurado y simbólico', 'En la expresión "su corazón es un témpano de hielo", ¿qué se quiere expresar mediante el lenguaje figurado?', '["Que la persona tiene una enfermedad física","Que la persona es fría o indiferente emocionalmente","Que la persona vive en un lugar muy frío","Que la persona practica deportes de invierno"]', 1, 'La metáfora del "témpano de hielo" asociada al corazón representa, de forma figurada, la frialdad o indiferencia emocional de una persona.', 'inicial', 60),
  ('Lenguaje figurado y simbólico', 'En un cuento, la luz del amanecer simboliza el inicio de una nueva etapa en la vida del protagonista. ¿Qué tipo de lenguaje se está utilizando?', '["Lenguaje literal","Lenguaje simbólico","Lenguaje técnico","Lenguaje coloquial"]', 1, 'Cuando un elemento concreto (la luz del amanecer) representa una idea abstracta (un nuevo comienzo), se está utilizando lenguaje simbólico.', 'intermedia', 90),
  ('Lenguaje figurado y simbólico', '¿Cuál de las siguientes frases usa lenguaje literal, y no figurado o simbólico?', '["El sol se puso a las 19:45 horas","Sus palabras fueron dagas en mi corazón","Ella es una tormenta cuando se enoja","El camino de la vida está lleno de piedras"]', 0, 'Indicar una hora exacta de un hecho es una descripción literal, sin ningún sentido figurado, a diferencia de las otras opciones.', 'intermedia', 90),
  ('Lenguaje figurado y simbólico', 'En un poema, la imagen de un ave enjaulada se repite para representar la falta de libertad del hablante lírico. ¿Qué función cumple este símbolo en el poema?', '["Ninguna, es solo una descripción de un animal","Representa de forma concreta y reiterada una idea abstracta: la falta de libertad","Sirve únicamente para hacer más largo el poema","Contradice el sentido general del poema"]', 1, 'Un símbolo literario, como el ave enjaulada, representa de manera concreta una idea abstracta que se refuerza mediante su repetición en el texto.', 'avanzada', 120),

  ('Validez de los argumentos de un texto', '¿Qué se entiende por un argumento válido dentro de un texto?', '["Una opinión repetida varias veces","Una razón fundamentada que apoya lógicamente una tesis","Cualquier afirmación, sin importar si tiene relación con el tema","Una afirmación exagerada para impresionar al lector"]', 1, 'Un argumento válido es una razón fundamentada, relacionada lógicamente con la tesis que pretende sustentar.', 'inicial', 60),
  ('Validez de los argumentos de un texto', 'Un texto afirma: "Debemos reducir el consumo de alimentos ultraprocesados porque estudios muestran que aumentan el riesgo de enfermedades". ¿Qué hace válido este argumento?', '["Que se presenta con seguridad y firmeza","Que se apoya en evidencia (estudios) relacionada con la tesis","Que es una opinión compartida por muchas personas","Que utiliza un vocabulario complejo"]', 1, 'La validez de un argumento depende de que se apoye en evidencia pertinente, como estudios, no de la seguridad con que se expresa.', 'intermedia', 90),
  ('Validez de los argumentos de un texto', '¿Cuál de los siguientes NO es un argumento válido para la tesis "se debe cuidar el agua potable"?', '["El agua potable es un recurso escaso en varias regiones del país","El derroche de agua afecta a las generaciones futuras","A mí me gusta mucho el color azul del agua","Cuidar el agua reduce el gasto en las cuentas del hogar"]', 2, 'Una preferencia estética personal (el color del agua) no constituye una razón lógica que sustente la tesis sobre cuidar el agua potable.', 'intermedia', 90),
  ('Validez de los argumentos de un texto', 'Un texto sostiene que "todos los adolescentes son irresponsables" basándose en la conducta de solo tres estudiantes de un colegio. ¿Qué problema de validez tiene este argumento?', '["Ninguno, tres casos son evidencia suficiente para toda una generalización","Es una generalización apresurada a partir de una muestra muy pequeña","Es un argumento completamente objetivo y verificable","Es válido porque se basa en hechos reales y concretos"]', 1, 'Generalizar sobre todo un grupo a partir de una muestra muy pequeña y poco representativa es un error argumentativo frecuente (generalización apresurada).', 'avanzada', 120),

  ('Relación del texto con su contexto histórico y social', '¿Por qué es importante relacionar un texto con su contexto histórico y social de producción?', '["Porque permite comprender mejor las ideas, valores y preocupaciones reflejadas en el texto","Porque el contexto no tiene relación alguna con el contenido del texto","Porque todos los textos se escriben de la misma forma sin importar la época","Porque solo interesa a los historiadores, no a los lectores de literatura"]', 0, 'Conocer el contexto histórico y social de un texto ayuda a comprender mejor las ideas, valores y preocupaciones que refleja.', 'inicial', 60),
  ('Relación del texto con su contexto histórico y social', 'Una novela escrita durante una dictadura incluye personajes que hablan en clave o con metáforas para evitar la censura. ¿Qué relación se puede establecer entre el texto y su contexto?', '["El contexto histórico no influyó en la forma de escribir la novela","El contexto de censura influyó en los recursos narrativos usados por el autor","El autor escribió sin ninguna intención relacionada con su época","La novela no tiene relación con hechos históricos reales"]', 1, 'El contexto de censura de una época puede explicar por qué un autor recurre a recursos como la metáfora o el lenguaje en clave.', 'intermedia', 90),
  ('Relación del texto con su contexto histórico y social', '¿Cuál de las siguientes afirmaciones sobre contexto histórico y social es incorrecta?', '["El contexto puede influir en los temas que aborda un autor","Conocer el contexto ayuda a interpretar mejor ciertos elementos del texto","El contexto histórico nunca afecta la forma en que se recibe o interpreta una obra","Distintas épocas pueden generar distintas interpretaciones de un mismo texto"]', 2, 'El contexto histórico sí puede afectar la forma en que se recibe e interpreta una obra a lo largo del tiempo; afirmar lo contrario es incorrecto.', 'intermedia', 90),
  ('Relación del texto con su contexto histórico y social', 'Un poema de comienzos del siglo XX habla de la industrialización con entusiasmo, mientras un poema actual sobre el mismo tema advierte sobre el daño ambiental. ¿Qué explica mejor esta diferencia?', '["Que uno de los dos poemas está mal escrito","Que el contexto histórico y social de cada época influye en la perspectiva del autor sobre un mismo tema","Que la industrialización nunca ha sido un tema literario","Que ambos poemas comparten exactamente la misma visión sobre el tema"]', 1, 'El contexto histórico y social de cada época (los conocimientos y preocupaciones ambientales disponibles) influye en la perspectiva de cada autor sobre un mismo tema.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Lectura')
      and name = 'Lectura — 8° Básico'
  )
cross join (select id from public.levels where code = 'regular_8_basico') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );

-- ============================================================================
-- EJE: ESCRITURA — 8° BÁSICO (4 objetivos x 4 preguntas = 16)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Textos argumentativos con estructura completa', '¿Qué elemento distingue a un texto argumentativo con estructura completa de uno breve o simple?', '["Que no necesita ninguna tesis","Que incluye introducción, desarrollo con varios argumentos y una conclusión elaborada","Que solo puede tener un argumento","Que no puede incluir contraargumentos"]', 1, 'Un texto argumentativo con estructura completa se organiza en introducción, desarrollo con varios argumentos y una conclusión que los integra, a diferencia de un texto breve.', 'inicial', 60),
  ('Textos argumentativos con estructura completa', 'Un estudiante escribe un ensayo argumentativo sobre la importancia del deporte escolar, incluyendo tres argumentos distintos y una posible objeción que refuta. ¿Qué logra al incluir la objeción?', '["Debilita su propio argumento sin ningún propósito","Fortalece su argumentación al anticiparse a una crítica y responderla","Contradice completamente su tesis inicial","Hace el texto más confuso para el lector"]', 1, 'Anticipar y refutar una posible objeción fortalece la argumentación, mostrando que el autor consideró otros puntos de vista.', 'intermedia', 90),
  ('Textos argumentativos con estructura completa', '¿Cuál de los siguientes elementos NO es parte de la estructura completa de un texto argumentativo?', '["Una tesis clara planteada al inicio","Varios argumentos que sustentan la tesis","Una conclusión que recoge los argumentos presentados","Un final donde se cambia por completo la tesis inicial sin justificación"]', 3, 'Cambiar la tesis al final sin justificación rompe la coherencia del texto argumentativo, que debe mantener y reforzar la misma tesis hasta la conclusión.', 'intermedia', 90),
  ('Textos argumentativos con estructura completa', 'Un estudiante redacta un texto argumentativo con varios argumentos, pero todos repiten la misma idea con palabras distintas. ¿Qué debería mejorar?', '["Nada, la repetición refuerza el argumento","Diversificar los argumentos, incorporando razones y evidencias distintas entre sí","Eliminar la tesis del texto","Agregar solo más adjetivos a cada argumento"]', 1, 'Un texto argumentativo sólido requiere argumentos diversos, no la misma idea repetida con distintas palabras.', 'avanzada', 120),

  ('Textos creativos con recursos estilísticos propios', '¿Qué significa que un estudiante desarrolle un recurso estilístico propio al escribir un texto creativo?', '["Copiar exactamente el estilo de un autor reconocido","Utilizar el lenguaje de una manera personal y distintiva, dentro de los recursos literarios aprendidos","Evitar cualquier uso de figuras literarias","Escribir siempre de la misma forma, sin variar el estilo"]', 1, 'Un recurso estilístico propio implica usar el lenguaje de forma personal, apoyándose en los recursos literarios aprendidos, sin copiar a otro autor.', 'inicial', 60),
  ('Textos creativos con recursos estilísticos propios', 'Un estudiante decide narrar un cuento intercalando fragmentos de diario íntimo del protagonista entre los capítulos. ¿Qué logra con esta decisión estilística?', '["Confundir al lector sin ningún propósito narrativo","Aportar una perspectiva más íntima y personal a la historia","Eliminar por completo la voz del narrador","Hacer el texto exactamente igual a uno tradicional"]', 1, 'Intercalar fragmentos de diario íntimo aporta una perspectiva más personal e interior del protagonista, enriqueciendo la narración.', 'intermedia', 90),
  ('Textos creativos con recursos estilísticos propios', '¿Cuál de las siguientes opciones NO corresponde a un recurso estilístico propio de la escritura creativa?', '["Elegir un tipo de narrador que aporte un efecto particular a la historia","Usar un lenguaje poético en las descripciones","Copiar palabra por palabra un texto de otro autor sin ninguna modificación","Combinar distintos tiempos narrativos de forma intencionada"]', 2, 'Copiar textualmente un texto ajeno no es un recurso estilístico propio, sino plagio; los recursos propios implican una elección personal del autor.', 'intermedia', 90),
  ('Textos creativos con recursos estilísticos propios', 'Un estudiante escribe un cuento donde repite una misma frase al inicio y al final del relato, para reforzar su sentido circular. ¿Qué recurso está utilizando?', '["Un recurso estructural o estilístico intencionado (estructura circular)","Un error de redacción que debería corregirse","Una repetición sin ningún propósito literario","Una falta de ortografía"]', 0, 'Repetir una frase al inicio y al final de un relato de forma intencionada es un recurso estilístico conocido como estructura circular.', 'avanzada', 120),

  ('Reescritura con coherencia, cohesión y corrección', 'Al reescribir un texto, ¿qué se entiende por "cohesión"?', '["Que las ideas generales del texto tengan sentido lógico entre sí","Que las oraciones estén correctamente conectadas mediante conectores y referencias","Que el texto no tenga faltas de ortografía","Que el texto sea muy extenso"]', 1, 'La cohesión se refiere a la correcta conexión gramatical entre oraciones y párrafos, mediante conectores, pronombres y otros recursos de enlace.', 'inicial', 60),
  ('Reescritura con coherencia, cohesión y corrección', 'Un estudiante revisa su texto y nota que usa la palabra "cosa" repetidamente para referirse a distintos conceptos. ¿Qué debería hacer para mejorar la cohesión y precisión del texto?', '["Dejarlo igual, no afecta la comprensión del texto","Reemplazar \"cosa\" por palabras más precisas según cada contexto","Eliminar todas las oraciones que contienen esa palabra","Agregar más veces la palabra \"cosa\" para mantener el estilo"]', 1, 'Reemplazar una palabra vaga como "cosa" por términos precisos mejora la claridad y la cohesión del texto.', 'intermedia', 90),
  ('Reescritura con coherencia, cohesión y corrección', '¿Cuál de las siguientes acciones NO corresponde a mejorar la coherencia de un texto al reescribirlo?', '["Ordenar las ideas de manera lógica","Eliminar ideas que contradicen el sentido general del texto","Agregar ideas sueltas sin relación con el tema central","Verificar que cada párrafo aporte al desarrollo del tema"]', 2, 'Agregar ideas sin relación con el tema central rompe la coherencia del texto, en vez de mejorarla.', 'intermedia', 90),
  ('Reescritura con coherencia, cohesión y corrección', 'Al reescribir un texto, un estudiante corrige la ortografía, pero mantiene oraciones desordenadas y sin conectores. ¿Qué aspecto de la reescritura no atendió correctamente?', '["La corrección ortográfica","La coherencia y cohesión del texto","El uso de mayúsculas","La extensión del texto"]', 1, 'Corregir la ortografía no basta si las oraciones siguen desordenadas y sin conectores: eso corresponde a un problema de coherencia y cohesión sin resolver.', 'avanzada', 120),

  ('Vocabulario amplio adecuado al género', '¿Por qué es importante usar un vocabulario amplio y preciso al escribir según el género textual?', '["Porque permite expresar ideas con mayor exactitud y adecuación al propósito del texto","Porque hace el texto más largo y complicado de leer","Porque impresiona al lector sin importar el sentido","Porque el vocabulario no afecta la comprensión del texto"]', 0, 'Un vocabulario amplio y preciso permite expresar ideas con mayor exactitud, adecuándose al propósito y al género del texto.', 'inicial', 60),
  ('Vocabulario amplio adecuado al género', 'Un estudiante escribe un informe científico y usa expresiones como "la cosa esa que pasó con las plantas". ¿Qué debería mejorar?', '["Nada, es un vocabulario adecuado para un informe científico","Reemplazar la expresión por un vocabulario técnico y preciso, propio del género","Usar aún más expresiones coloquiales para dar cercanía","Eliminar por completo el tema de las plantas"]', 1, 'Un informe científico requiere un vocabulario técnico y preciso, no expresiones coloquiales vagas como "la cosa esa".', 'intermedia', 90),
  ('Vocabulario amplio adecuado al género', '¿Cuál de las siguientes opciones usa un vocabulario más adecuado para un texto expositivo escolar?', '["La fotosíntesis es como la cosa que hacen las plantas para comer","La fotosíntesis es el proceso mediante el cual las plantas producen su propio alimento","Las plantas hacen sus cosas con la luz, no sé bien cómo","Fotosíntesis, o sea, eso que se ve en los libros"]', 1, 'La segunda opción define el concepto con precisión y vocabulario técnico adecuado a un texto expositivo escolar.', 'intermedia', 90),
  ('Vocabulario amplio adecuado al género', 'Un estudiante debe escribir un cuento de terror y uno humorístico sobre un mismo tema. ¿Qué estrategia de vocabulario es más adecuada?', '["Usar exactamente el mismo vocabulario en ambos textos","Adaptar el vocabulario y el tono según el género (tenso y sombrío para terror, ligero y jocoso para humor)","Usar solo vocabulario técnico en ambos casos","Evitar cualquier adjetivo en los dos textos"]', 1, 'Adaptar el vocabulario y el tono según el género textual permite lograr el efecto buscado en cada caso (terror o humor).', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Escritura')
      and name = 'Escritura — 8° Básico'
  )
cross join (select id from public.levels where code = 'regular_8_basico') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );

-- ============================================================================
-- EJE: COMUNICACIÓN ORAL — 8° BÁSICO (4 objetivos x 4 preguntas = 16)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Discursos orales con propósito persuasivo', '¿Cuál es el objetivo principal de un discurso oral con propósito persuasivo?', '["Informar datos sin intentar convencer a nadie","Convencer a la audiencia de adoptar una idea, opinión o acción","Entretener sin ningún contenido argumentativo","Describir un lugar de forma neutra"]', 1, 'Un discurso persuasivo busca convencer a la audiencia de adoptar una idea, opinión o acción determinada.', 'inicial', 60),
  ('Discursos orales con propósito persuasivo', 'Un estudiante prepara un discurso para convencer a sus compañeros de participar en una campaña solidaria. ¿Qué recurso sería más efectivo incluir?', '["Solo datos sin ninguna conexión emocional con la audiencia","Argumentos sólidos junto con ejemplos que generen empatía en la audiencia","Un discurso extremadamente extenso sin ninguna estructura","Palabras técnicas difíciles de comprender para el público"]', 1, 'Combinar argumentos sólidos con ejemplos que generen empatía fortalece el efecto persuasivo de un discurso.', 'intermedia', 90),
  ('Discursos orales con propósito persuasivo', '¿Cuál de los siguientes recursos NO es propio de un discurso persuasivo bien construido?', '["Presentar argumentos con evidencia","Conectar emocionalmente con la audiencia de forma genuina","Exagerar o inventar datos falsos para convencer más fácilmente","Utilizar un cierre que refuerce la idea principal"]', 2, 'Inventar o exagerar datos falsos no corresponde a un discurso persuasivo bien construido, sino a una práctica poco ética y poco rigurosa.', 'intermedia', 90),
  ('Discursos orales con propósito persuasivo', 'Un estudiante nota que su discurso persuasivo, aunque bien argumentado, no logra conectar con la audiencia. ¿Qué estrategia podría mejorar su impacto?', '["Aumentar la cantidad de datos técnicos sin ninguna conexión con la audiencia","Incorporar ejemplos cercanos a la experiencia de la audiencia y cuidar el tono de voz","Leer el discurso completo sin ninguna variación de entonación","Reducir el contacto visual con el público"]', 1, 'Incorporar ejemplos cercanos a la audiencia y cuidar el tono de voz ayuda a generar una conexión más efectiva con el público.', 'avanzada', 120),

  ('Foros o mesas redondas defendiendo una postura', 'En un foro o mesa redonda, ¿qué se espera de un participante al defender una postura?', '["Que presente argumentos y esté dispuesto a escuchar otras posturas","Que repita su opinión sin escuchar a los demás participantes","Que hable todo el tiempo sin dar espacio a otros","Que evite dar cualquier razón que sustente su postura"]', 0, 'Defender una postura en un foro implica presentar argumentos propios, además de escuchar y considerar las posturas de los demás participantes.', 'inicial', 60),
  ('Foros o mesas redondas defendiendo una postura', 'Durante una mesa redonda sobre el uso de plásticos, un participante escucha un argumento nuevo y ajusta parcialmente su postura inicial. ¿Qué actitud demuestra este participante?', '["Una actitud de escucha crítica y disposición a considerar otros argumentos","Una falta de convicción en su propia postura","Un error grave dentro de una mesa redonda","Una contradicción que invalida su participación"]', 0, 'Ajustar una postura al considerar un argumento nuevo y válido demuestra escucha crítica, una actitud valorada en una mesa redonda.', 'intermedia', 90),
  ('Foros o mesas redondas defendiendo una postura', '¿Cuál de las siguientes actitudes NO es adecuada en una mesa redonda?', '["Escuchar atentamente a los demás participantes","Fundamentar la propia postura con argumentos","Interrumpir constantemente a quien tiene la palabra","Respetar los turnos de habla establecidos"]', 2, 'Interrumpir constantemente a otros participantes contradice las normas básicas de respeto y organización de una mesa redonda.', 'intermedia', 90),
  ('Foros o mesas redondas defendiendo una postura', 'En una mesa redonda, dos participantes defienden posturas opuestas sobre la reducción de la jornada laboral, cada uno con argumentos sólidos y evidencia distinta. ¿Qué se puede concluir sobre esta situación?', '["Solo uno de los dos puede tener razón, sin importar la evidencia","Un tema complejo puede sostener posturas distintas, cada una fundamentada de forma diferente","La mesa redonda no cumplió su propósito por haber desacuerdo","La existencia de dos posturas indica que ambas están mal fundamentadas"]', 1, 'En temas complejos, distintas posturas pueden estar bien fundamentadas a partir de evidencia y enfoques diferentes.', 'avanzada', 120),

  ('Análisis crítico de discursos audiovisuales', 'Al analizar críticamente un aviso publicitario, ¿qué es relevante identificar?', '["Solo el color y el diseño del aviso","La intención persuasiva y los recursos usados para convencer al público","La duración exacta en segundos del aviso","El nombre de la empresa productora del aviso"]', 1, 'El análisis crítico de un aviso publicitario se centra en identificar su intención persuasiva y los recursos empleados para convencer a la audiencia.', 'inicial', 60),
  ('Análisis crítico de discursos audiovisuales', 'Un noticiero muestra imágenes de un evento acompañadas de música dramática y un tono de voz alarmante. ¿Qué función cumplen estos recursos audiovisuales?', '["Ninguna, son elementos neutros sin ninguna intención","Buscan generar un efecto emocional específico en la audiencia","Solo sirven para llenar tiempo en el noticiero","Son obligatorios en cualquier noticiero, sin ningún propósito comunicativo"]', 1, 'La música dramática y el tono alarmante son recursos que buscan generar un efecto emocional determinado en quienes ven el noticiero.', 'intermedia', 90),
  ('Análisis crítico de discursos audiovisuales', '¿Cuál de los siguientes elementos NO forma parte del análisis crítico de un discurso audiovisual?', '["La intención comunicativa del mensaje","Los recursos visuales y sonoros utilizados","El precio del equipo usado para grabar el video","El público al que está dirigido el mensaje"]', 2, 'El costo del equipo de grabación no es relevante para el análisis crítico del mensaje, a diferencia de la intención, los recursos y el público destinatario.', 'intermedia', 90),
  ('Análisis crítico de discursos audiovisuales', 'Un comercial de un producto para adelgazar presenta solo testimonios de personas satisfechas, sin mostrar ningún dato científico. ¿Qué debilidad se puede identificar desde un análisis crítico?', '["Ninguna, los testimonios son siempre una prueba suficiente","La falta de evidencia científica que respalde las afirmaciones del comercial","El comercial es completamente objetivo por mostrar personas reales","Los testimonios equivalen a un estudio científico riguroso"]', 1, 'Basarse únicamente en testimonios, sin evidencia científica, es una debilidad frecuente que un análisis crítico debe identificar.', 'avanzada', 120),

  ('Recursos verbales y no verbales efectivos', '¿Qué se entiende por recursos no verbales en la comunicación oral?', '["Las palabras exactas que se utilizan en el discurso","Gestos, postura corporal, contacto visual y tono de voz","El contenido escrito del discurso","La ortografía del texto que se lee"]', 1, 'Los recursos no verbales corresponden a elementos como gestos, postura corporal, contacto visual y tono de voz, distintos del contenido verbal (las palabras).', 'inicial', 60),
  ('Recursos verbales y no verbales efectivos', 'Durante una exposición, un estudiante mira constantemente el suelo y habla en un volumen muy bajo. ¿Qué efecto tiene esto en la comunicación con el público?', '["Ninguno, el contenido es lo único que importa","Dificulta la conexión con el público y puede transmitir inseguridad","Mejora la comprensión del discurso","Es la forma correcta de exponer frente a un curso"]', 1, 'Evitar el contacto visual y hablar en voz muy baja dificulta la conexión con el público y puede transmitir inseguridad al expositor.', 'intermedia', 90),
  ('Recursos verbales y no verbales efectivos', '¿Cuál de las siguientes opciones NO corresponde a un recurso no verbal efectivo en una exposición oral?', '["Mantener contacto visual con distintas partes del público","Variar el tono de voz según el contenido expuesto","Hablar de espaldas al público durante toda la exposición","Usar gestos que acompañen y refuercen lo que se dice"]', 2, 'Hablar de espaldas al público impide el contacto visual y dificulta la comunicación, por lo que no es un recurso no verbal efectivo.', 'intermedia', 90),
  ('Recursos verbales y no verbales efectivos', 'Un estudiante domina el contenido de su exposición, pero su tono de voz es monótono durante toda la presentación. ¿Qué recomendación es más adecuada?', '["Mantener el mismo tono, ya que el contenido es lo único relevante","Variar el tono de voz para enfatizar ideas clave y mantener la atención del público","Hablar cada vez más rápido para terminar antes","Reducir aún más las variaciones de volumen"]', 1, 'Variar el tono de voz ayuda a enfatizar ideas clave y a mantener la atención del público durante toda la exposición.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Comunicación Oral')
      and name = 'Comunicación Oral — 8° Básico'
  )
cross join (select id from public.levels where code = 'regular_8_basico') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );

-- ============================================================================
-- EJE: INVESTIGACIÓN — 8° BÁSICO (4 objetivos x 4 preguntas = 16)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Preguntas de investigación relevantes', '¿Qué caracteriza a una buena pregunta de investigación?', '["Que pueda responderse con un simple sí o no sin ningún desarrollo","Que sea clara, específica y permita una indagación profunda del tema","Que sea lo más general y ambigua posible","Que no tenga relación directa con el tema elegido"]', 1, 'Una buena pregunta de investigación debe ser clara y específica, de modo que permita una indagación profunda del tema.', 'inicial', 60),
  ('Preguntas de investigación relevantes', 'Un estudiante plantea la pregunta: "¿Por qué algunos ríos de Chile presentan mayor contaminación que otros?". ¿Qué característica de una buena pregunta de investigación cumple?', '["Es demasiado amplia para investigarse","Es específica y orienta una indagación sobre causas concretas","No tiene relación con ningún tema científico o social","Solo puede responderse con sí o no"]', 1, 'La pregunta orienta una indagación específica sobre causas concretas de un fenómeno, característica de una buena pregunta de investigación.', 'intermedia', 90),
  ('Preguntas de investigación relevantes', '¿Cuál de las siguientes preguntas es menos adecuada para guiar una investigación escolar?', '["¿Qué factores influyen en la migración de una especie de aves en Chile?","¿Es bonita la naturaleza?","¿Cómo ha cambiado el uso del agua en la agricultura en los últimos 20 años?","¿Qué medidas se han tomado para proteger un ecosistema específico?"]', 1, 'La pregunta "¿es bonita la naturaleza?" es demasiado subjetiva y general, y no permite una indagación investigativa concreta.', 'intermedia', 90),
  ('Preguntas de investigación relevantes', 'Un estudiante formula la pregunta "¿es buena o mala la tecnología?". ¿Qué problema tiene esta pregunta para orientar una investigación?', '["Ninguno, es una pregunta perfectamente investigable tal como está","Es demasiado general y subjetiva; debería reformularse de forma más específica y objetiva","Es una pregunta demasiado específica para investigarse","No tiene ninguna relación con el tema de tecnología"]', 1, 'Una pregunta tan general y valorativa dificulta una investigación concreta; conviene reformularla enfocándola en un aspecto específico.', 'avanzada', 120),

  ('Contrastación de fuentes diversas', '¿Qué significa contrastar información proveniente de diversas fuentes?', '["Elegir una sola fuente y descartar todas las demás","Comparar los datos de distintas fuentes para verificar su coincidencia o discrepancia","Copiar la información de la primera fuente encontrada","Ignorar las diferencias entre las fuentes consultadas"]', 1, 'Contrastar fuentes implica comparar sus datos para verificar si coinciden o difieren entre sí.', 'inicial', 60),
  ('Contrastación de fuentes diversas', 'Un estudiante encuentra que tres fuentes coinciden en un dato, mientras una cuarta fuente lo contradice sin citar respaldo. ¿Qué debería hacer?', '["Confiar más en la fuente que contradice a las demás sin cuestionar nada","Dar mayor validez al dato respaldado por la coincidencia de varias fuentes confiables","Ignorar completamente el tema por existir una contradicción","Elegir al azar cuál información usar"]', 1, 'Ante una contradicción, es razonable dar mayor validez al dato respaldado por varias fuentes confiables que coinciden entre sí.', 'intermedia', 90),
  ('Contrastación de fuentes diversas', '¿Cuál de las siguientes acciones NO corresponde a un proceso adecuado de contrastación de fuentes?', '["Comparar los datos entregados por distintas fuentes","Verificar la fecha y autoría de cada fuente","Aceptar sin revisión la primera fuente encontrada en una búsqueda","Buscar coincidencias o discrepancias entre las fuentes consultadas"]', 2, 'Aceptar sin revisión la primera fuente encontrada contradice el propósito de contrastar información entre varias fuentes.', 'intermedia', 90),
  ('Contrastación de fuentes diversas', 'Al investigar sobre un fenómeno social, un estudiante encuentra que las fuentes académicas y las fuentes periodísticas presentan matices distintos sobre el mismo hecho. ¿Qué estrategia es más adecuada?', '["Usar solo una de las dos categorías de fuentes, ignorando la otra por completo","Reconocer los distintos enfoques y complementarlos para una comprensión más completa","Descartar automáticamente todas las fuentes periodísticas","Concluir que un fenómeno solo puede explicarse desde un enfoque"]', 1, 'Reconocer y complementar distintos enfoques (académico y periodístico) permite una comprensión más completa de un fenómeno social.', 'avanzada', 120),

  ('Citación básica de fuentes', '¿Por qué es importante citar las fuentes consultadas en una investigación?', '["Para dar crédito a los autores originales y evitar el plagio","Porque es un requisito sin ningún propósito real","Para hacer el texto más largo","Porque las citas reemplazan la necesidad de investigar"]', 0, 'Citar las fuentes da crédito a los autores originales de las ideas o datos utilizados y evita el plagio.', 'inicial', 60),
  ('Citación básica de fuentes', 'Un estudiante copia un párrafo textual de un libro sin indicar de dónde lo obtuvo. ¿Qué problema ético y académico presenta esta acción?', '["Ninguno, si el contenido es útil no es necesario citarlo","Constituye un plagio, al presentar como propias las ideas de otro autor","Es una práctica recomendada en cualquier investigación","Solo es un problema si el libro es muy conocido"]', 1, 'Copiar texto sin citar la fuente original constituye un plagio, independientemente de qué tan conocido sea el libro.', 'intermedia', 90),
  ('Citación básica de fuentes', '¿Cuál de las siguientes opciones corresponde a una citación básica adecuada de una fuente?', '["Copiar el texto sin ninguna referencia a su origen","Indicar el autor, el título de la fuente y, si es posible, el año de publicación","Solo mencionar que \"se investigó en internet\"","Omitir cualquier referencia porque el contenido es de conocimiento público"]', 1, 'Una citación básica adecuada indica al menos el autor, el título de la fuente y, si es posible, el año de publicación.', 'intermedia', 90),
  ('Citación básica de fuentes', 'Un estudiante parafrasea (reescribe con sus propias palabras) una idea de un autor, pero no menciona de dónde proviene esa idea. ¿Es esto correcto?', '["Sí, porque al parafrasear ya no es necesario citar la fuente","No, porque incluso al parafrasear se debe reconocer la fuente original de la idea","Sí, solo se debe citar cuando se copia textualmente","No tiene importancia si la idea es parafraseada o copiada"]', 1, 'Aunque se reescriba una idea con palabras propias, la fuente original debe reconocerse igualmente, ya que la idea no es propia del estudiante.', 'avanzada', 120),

  ('Informe de investigación con conclusiones propias', '¿Qué debe incluir un informe de investigación además de la información recopilada?', '["Únicamente una lista de fuentes consultadas","Conclusiones propias que sinteticen lo aprendido durante la investigación","Solo las preguntas planteadas al inicio, sin ningún desarrollo","Una copia textual de todas las fuentes usadas"]', 1, 'Un informe de investigación debe incluir conclusiones propias que sinteticen e integren lo aprendido, además de la información recopilada.', 'inicial', 60),
  ('Informe de investigación con conclusiones propias', 'Un estudiante redacta un informe donde solo resume lo que dice cada fuente, sin agregar ninguna conclusión personal. ¿Qué le falta a su informe?', '["Nada, el informe está completo tal como está","Una síntesis o conclusión propia que integre y valore la información recopilada","Más fuentes, sin importar las conclusiones","Una portada más llamativa"]', 1, 'Un informe de investigación no debe limitarse a resumir fuentes; requiere una síntesis o conclusión propia que integre esa información.', 'intermedia', 90),
  ('Informe de investigación con conclusiones propias', '¿Cuál de las siguientes opciones NO corresponde a una conclusión adecuada para un informe de investigación?', '["Una síntesis de los hallazgos más relevantes de la investigación","Una reflexión personal fundamentada en la información recopilada","Una opinión sin ninguna relación con la información investigada","Una respuesta a la pregunta de investigación planteada al inicio"]', 2, 'Una opinión sin relación con la información investigada no constituye una conclusión válida, ya que debe fundamentarse en lo investigado.', 'intermedia', 90),
  ('Informe de investigación con conclusiones propias', 'Un estudiante investiga sobre el reciclaje en su comuna y concluye, a partir de los datos recopilados, que faltan puntos de reciclaje accesibles para la comunidad. ¿Qué característica cumple esta conclusión?', '["Es una opinión sin ninguna relación con la investigación","Es una conclusión propia fundamentada en la evidencia recopilada durante la investigación","Es una copia textual de una de las fuentes consultadas","No corresponde a una conclusión válida para un informe"]', 1, 'La conclusión surge del análisis de los datos recopilados durante la investigación, por lo que es una conclusión propia fundamentada.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Investigación')
      and name = 'Investigación — 8° Básico'
  )
cross join (select id from public.levels where code = 'regular_8_basico') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );
